import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        # Use the actual t-statistic from feats.types
        t_stat = feats.types[i]
        # Check if t_stat is actually a number, if not skip
        try:
            if abs(t_stat) > 2.0:
                strong_candidates.append((fid, t_stat))
        except TypeError:
            continue

    # Sort by absolute t-statistic
    strong_candidates.sort(key=lambda x: abs(x[1]), reverse=True)

    # Remove near-duplicates (correlated features)
    correlated_pairs = set()
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            corr_coef = np.corrcoef(feats.x[:,i], feats.x[:,j])[0,1]
            if abs(corr_coef) >= 0.6:
                fid1, fid2 = feats.ids[i], feats.ids[j]
                correlated_pairs.add((min(fid1,fid2), max(fid1,fid2)))

    # Group correlated features and select representative
    groups = defaultdict(list)
    for fid, _ in strong_candidates:
        matched = False
        for group in groups.values():
            if any((min(fid,gid), max(fid,gid)) in correlated_pairs for gid in group):
                group.append(fid)
                matched = True
                break
        if not matched:
            groups[frozenset([fid])] = [fid]

    # Select best from each group
    selected_features = []
    for group in groups.values():
        if len(group) == 1:
            selected_features.extend(group)
        else:
            # Prefer the one with highest absolute t-statistic
            group_t_stats = [(fid, feats.types[feats.column(fid)]) for fid in group]
            best_fid = max(group_t_stats, key=lambda x: abs(x[1]))[0]
            selected_features.append(best_fid)

    # Limit to MAX_DRIVERS
    selected_features = selected_features[:MAX_DRIVERS]

    # If no strong features, return empty design
    if not selected_features:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build design with selected features
    drivers = tuple(selected_features)
    columns = tuple(selected_features)

    # Add pairwise interactions for top features
    products = []
    for i in range(min(3, len(selected_features))):
        for j in range(i+1, min(3, len(selected_features))):
            products.append((selected_features[i], selected_features[j]))

    # Simple weighting based on effect size
    loadings = {}
    for fid in selected_features:
        idx = feats.column(fid)
        loadings[fid] = feats.types[idx]

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

